/* Escritor: editor de libros sin distracciones */
#include "z.h"
typedef struct { char name[80]; char *txt; long len; } sec_t;
#define MAXS 300
#define SW 240
#define HH 44
static zwin *W, *FW; static te_t T; static sec_t S[MAXS]; static int ns, cur, stop, zoom = 1, dark, typew = 1; static char title[100] = "", path[320], dir[200], st[100]; static int foc = 0, tc, sc2; /* 0 texto, 1 titulo, 2 seccion */
static int dirty, start_words; static u64 last_edit;
static const u32 PG[2] = {0xFBF8F1, 0x1C1F24}, FG[2] = {0x2A2723, 0xD8D3C8}, SL[2] = {0xE6DCC6, 0x3A4048};
static void sec_add(const char *n, const char *t, long l) { if (ns >= MAXS) return; sec_t *s = &S[ns++]; strncpy0(s->name, n, 80); s->txt = malloc(l + 1); memcpy(s->txt, t, l); s->txt[l] = 0; s->len = l; }
static void keep(void) { sec_t *s = &S[cur]; free(s->txt); s->txt = malloc(T.len + 1); memcpy(s->txt, T.t, T.len + 1); s->len = T.len; }
static void go(int i) { keep(); cur = i; te_set(&T, S[i].txt, S[i].len); T.cur = S[i].len; foc = 0; }
static int chap_count(void) { return ns - 3; }
static int total_words(void) { keep(); int w = 0; for (int i = 0; i < ns; i++) w += te_words(S[i].txt, S[i].len); return w; }
static long total_chars(void) { long c = 0; for (int i = 0; i < ns; i++) { for (long k = 0; k < S[i].len; k++) if ((S[i].txt[k] & 0xC0) != 0x80) c++; } return c; }
static void newbook(void) { for (int i = 0; i < ns; i++) free(S[i].txt); ns = 0; sec_add("Portada", "", 0); sec_add("Prefacio", "", 0); sec_add("Capitulo 1", "", 0); sec_add("Contraportada", "", 0); cur = 2; te_set(&T, "", 0); title[0] = 0; path[0] = 0; dirty = 0; start_words = 0; }
static void safe(const char *s, char *o, int c) { int k = 0; for (; *s && k < c - 1; s++) o[k++] = strchr("/\\:*?\"<>|", *s) ? '_' : *s; o[k] = 0; if (!k) strcpy(o, _("Sin titulo")); }
static void ser(sb_t *b) { keep(); sb_s(b, "ZESCRITOR1\n"); sb_s(b, title); sb_s(b, "\n"); for (int i = 0; i < ns; i++) { sb_s(b, "\x1e"); sb_s(b, S[i].name); sb_s(b, "\n"); sb_add(b, S[i].txt, S[i].len); } }
static void save(void) { char n[100], bak[340]; safe(title[0] ? title : "Sin titulo", n, 90); char np[320]; snprintf(np, 320, "%s/%s.zes", dir, n); if (path[0] && strcmp(path, np)) { z_rename(path, np); } strcpy(path, np); snprintf(bak, 340, "%s.bak", path); sb_t b = {0}; ser(&b); z_unlink(bak); z_rename(path, bak); int e = z_writefile(path, b.p, b.n); free(b.p); if (e) snprintf(st, 100, _("Error al guardar: %s"), z_errstr(e)); else { dirty = 0; strcpy(st, _("Guardado")); z_log("[prueba] escritor guardo"); } }
static int load(const char *p) { long n; char *d = z_readfile(p, &n); if (!d) return -2; if (strncmp(d, "ZESCRITOR1\n", 11)) { free(d); return -22; } for (int i = 0; i < ns; i++) free(S[i].txt); ns = 0; char *q = d + 11, *e = strchr(q, '\n'); if (!e) { free(d); newbook(); return -22; } *e = 0; strncpy0(title, q, 100); q = e + 1; while (*q == 0x1e) { q++; char *nl = strchr(q, '\n'); if (!nl) break; *nl = 0; char *t = nl + 1, *z = strchr(t, 0x1e); long l = z ? z - t : (long)strlen(t); sec_add(q, t, l); if (!z) break; q = z; } free(d); if (ns < 3) newbook(); strncpy0(path, p, 320); cur = ns > 3 ? 2 : 0; te_set(&T, S[cur].txt, S[cur].len); T.cur = T.len; dirty = 0; start_words = total_words(); return 0; }
static void import_(const char *p) { long n; char *d = doc_import(p, &n); if (!d) { strcpy(st, _("No se pudo importar")); return; } newbook(); const char *b = strrchr(p, '/'); b = b ? b + 1 : p; strncpy0(title, b, 100); char *x = strrchr(title, '.'); if (x) *x = 0; free(S[2].txt); S[2].txt = d; S[2].len = n; te_set(&T, d, n); dirty = 1; char m[100]; snprintf(m, 100, "[prueba] escritor importo %ld bytes, %d palabras", n, te_words(d, n)); z_log(m); strcpy(st, _("Documento importado")); }
static int scols(int w) { return MIN(76, (w - 60) / (8 * zoom)); }
static void draw_text(zwin *o, int x, int y, int w, int h, int fm) { int c = scols(w), pw = c * 8 * zoom; T.cols = c; T.changed |= 0; int px = x + (w - pw) / 2; g_rect(o, x, y, w, h, PG[dark]); zw_clip(o, x, y, w, h); te_draw(o, &T, px, y + 18, h - 36, zoom, FG[dark], SL[dark], dark ? 0x5EEAD4 : 0x0F766E, fm && typew); zw_noclip(o); }
static void draw(void) {
    g_rect(W, 0, 0, SW, W->h, 0x20242B); g_textb(W, 14, 10, "Escritor", 0xF3EFE6); g_text(W, 14, 28, "sin distracciones", 0x8D96A3); int f = foc == 1; g_text(W, 14, 52, "Libro", 0x8D96A3); ui_input(W, 12, 70, SW - 24, 26, title, tc, f); int y = 104, h = W->h - 104 - 150, vis = h / 24; zw_clip(W, 0, y, SW, h); for (int i = stop; i < ns && i < stop + vis; i++) { int Y = y + (i - stop) * 24; if (i == cur) g_rect(W, 0, Y, SW, 24, 0x0F766E); char b[100]; int wc = i == cur ? te_words(T.t, T.len) : te_words(S[i].txt, S[i].len); snprintf(b, 100, "%d", wc); zw_clip(W, 14, Y, SW - 70, 24); g_text(W, 14, Y + 4, S[i].name, 0xF3EFE6); zw_clip(W, 0, y, SW, h); g_text(W, SW - 12 - g_textw(b), Y + 4, b, 0x9CA3AF); } zw_noclip(W); int by = W->h - 146; ui_button(W, 12, by, 104, 26, "+ Capitulo", 0); ui_button(W, 122, by, 106, 26, "Borrar", 0); ui_button(W, 12, by + 30, 104, 26, "Proyectos", 0); ui_button(W, 122, by + 30, 106, 26, "Exportar", 0); ui_button(W, 12, by + 60, 216, 26, "Concentracion (F11)", 2); int tw = total_words(); char s[80]; snprintf(s, 80, _("%d palabras"), tw); g_text(W, 14, by + 94, s, 0xF3EFE6); snprintf(s, 80, _("%ld caracteres"), total_chars()); g_text(W, 14, by + 110, s, 0x9CA3AF); snprintf(s, 80, _("Sesion: %+d"), tw - start_words); (void)0; if (tw >= start_words) snprintf(s, 80, _("Hoy: +%d"), tw - start_words); else snprintf(s, 80, _("Hoy: %d"), tw - start_words); g_text(W, 140, by + 94, s, 0x5EEAD4);
    g_rect(W, SW, 0, W->w - SW, HH, UI_PANEL); ui_input(W, SW + 12, 9, 280, 26, S[cur].name, sc2, foc == 2); g_text(W, SW + 304, 14, st, UI_MUTED); ui_button(W, W->w - 150, 9, 36, 26, zoom > 1 ? "A-" : "A+", 0); ui_button(W, W->w - 110, 9, 44, 26, dark ? "Dia" : "Nch", 0); ui_button(W, W->w - 62, 9, 52, 26, "Guarda", 0); draw_text(W, SW, HH, W->w - SW, W->h - HH, 0); zw_present(W);
}
static void draw_focus(void) { draw_text(FW, 0, 0, FW->w, FW->h - 24, 1); g_rect(FW, 0, FW->h - 24, FW->w, 24, PG[dark]); char b[100]; snprintf(b, 100, _("%s   %d palabras   Esc para salir"), S[cur].name, te_words(T.t, T.len)); g_text(FW, (FW->w - g_textw(b)) / 2, FW->h - 20, b, dark ? 0x5B626D : 0xB7AE9C); zw_present(FW); }
static void redraw(void) { if (FW) draw_focus(); else draw(); }
static void toggle_focus(void) { if (FW) { zw_close(FW); FW = 0; draw(); return; } zsys s; z_sysinfo(&s); FW = zw_new("Concentracion", 0, 0, s.scr_w, s.scr_h, WF_POPUP); foc = 0; draw_focus(); }
/* --- exportar --- */
static void plain(sb_t *b, int md) { keep(); if (md) sb_f(b, "# %s\n\n", title); else { sb_f(b, "%s\n", title); for (int i = 0, n = strlen(title); i < n; i++) sb_s(b, "="); sb_s(b, "\n\n"); } for (int i = 0; i < ns; i++) { if (!S[i].len) continue; if (md) sb_f(b, "## %s\n\n", S[i].name); else { sb_f(b, "%s\n", S[i].name); for (int k = 0, n = strlen(S[i].name); k < n; k++) sb_s(b, "-"); sb_s(b, "\n"); } sb_add(b, S[i].txt, S[i].len); sb_s(b, "\n\n"); } }
static void paras(sb_t *b, const char *t, long n, const char *o, const char *c) { long i = 0; while (i < n) { long e = i; while (e < n && t[e] != '\n') e++; if (e > i) { sb_s(b, o); sb_esc(b, t + i, e - i); sb_s(b, c); } i = e + 1; } }
static void rtf_str(sb_t *b, const char *s, long n) { const char *p = s, *e = s + n; while (p < e) { const char *q = p; int c = utf8_next(&q); if (q > e || !c) break; p = q; if (c == '\\' || c == '{' || c == '}') sb_f(b, "\\%c", c); else if (c == '\n') sb_s(b, "\\par\n"); else if (c < 128) sb_add(b, (char[]){(char)c}, 1); else sb_f(b, "\\u%d?", c > 32767 ? c - 65536 : c); } }
static const char *DX1 = "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/></Types>";
static const char *DX2 = "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"word/document.xml\"/></Relationships>";
static int export_(int k) { static const char *E[] = {"txt", "md", "html", "rtf", "docx"}; char n[100], p[340], ed[260]; safe(title[0] ? title : "Sin titulo", n, 90); snprintf(ed, 260, "%s/EXPORTADOS", dir); z_mkdir(ed); snprintf(p, 340, "%s/%s.%s", ed, n, E[k]); keep(); sb_t b = {0}; int e;
    if (k < 2) plain(&b, k); else if (k == 2) { sb_s(&b, "<!doctype html><html><head><meta charset=\"utf-8\"><title>"); sb_esc(&b, title, strlen(title)); sb_s(&b, "</title><style>body{max-width:40em;margin:3em auto;font-family:serif;line-height:1.6}</style></head><body><h1>"); sb_esc(&b, title, strlen(title)); sb_s(&b, "</h1>"); for (int i = 0; i < ns; i++) if (S[i].len) { sb_s(&b, "<h2>"); sb_esc(&b, S[i].name, strlen(S[i].name)); sb_s(&b, "</h2>"); paras(&b, S[i].txt, S[i].len, "<p>", "</p>\n"); } sb_s(&b, "</body></html>"); }
    else if (k == 3) { sb_s(&b, "{\\rtf1\\ansi\\deff0{\\fonttbl{\\f0 Times New Roman;}}\\f0\\fs24\n{\\b\\fs40 "); rtf_str(&b, title, strlen(title)); sb_s(&b, "\\par}\n"); for (int i = 0; i < ns; i++) if (S[i].len) { sb_s(&b, "{\\b\\fs30 "); rtf_str(&b, S[i].name, strlen(S[i].name)); sb_s(&b, "\\par}\n"); rtf_str(&b, S[i].txt, S[i].len); sb_s(&b, "\\par\n"); } sb_s(&b, "}"); }
    else { sb_s(&b, "<?xml version=\"1.0\" encoding=\"UTF-8\"?><w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body><w:p><w:r><w:rPr><w:b/><w:sz w:val=\"44\"/></w:rPr><w:t>"); sb_esc(&b, title, strlen(title)); sb_s(&b, "</w:t></w:r></w:p>"); for (int i = 0; i < ns; i++) if (S[i].len) { sb_s(&b, "<w:p><w:r><w:rPr><w:b/><w:sz w:val=\"32\"/></w:rPr><w:t>"); sb_esc(&b, S[i].name, strlen(S[i].name)); sb_s(&b, "</w:t></w:r></w:p>"); paras(&b, S[i].txt, S[i].len, "<w:p><w:r><w:t xml:space=\"preserve\">", "</w:t></w:r></w:p>"); } sb_s(&b, "<w:sectPr/></w:body></w:document>"); const char *N[] = {"[Content_Types].xml", "_rels/.rels", "word/document.xml"}; const char *D[] = {DX1, DX2, b.p}; long L[] = {(long)strlen(DX1), (long)strlen(DX2), b.n}; e = zip_save(p, 3, N, D, L); free(b.p); goto done; }
    e = z_writefile(p, b.p, b.n); free(b.p);
done: if (e) snprintf(st, 100, "Error: %s", z_errstr(e)); else snprintf(st, 100, _("Exportado en EXPORTADOS")); char m[380]; snprintf(m, 380, "[prueba] escritor exporto %s: %s", p, e ? z_errstr(e) : "OK"); z_log(m); return e; }
/* elige una opcion de una lista */
static int pick(const char *t, const char **it, int n) { zsys s; z_sysinfo(&s); int h = MIN(n, 16) * 30 + 44; zwin *d = zw_new(t, (s.scr_w - 420) / 2, (s.scr_h - h) / 2, 420, h, WF_DECOR); int r = -2; zevent e; while (r == -2) { g_clear(d, UI_BG); for (int i = 0; i < n && i < 16; i++) ui_button(d, 12, 8 + i * 30, 396, 26, it[i], 0); ui_button(d, 300, h - 32, 108, 26, "Cancelar", 0); zw_present(d); if (!z_event(&e, -1) || e.win != (u32)d->id) continue; if (e.type == EV_CLOSE || (e.type == EV_KEY && e.ch == 27)) r = -1; else if (e.type == EV_KEY && e.ch >= '1' && e.ch < (u32)'1' + MIN(n, 9)) r = e.ch - '1'; else if (e.type == EV_DOWN) { if (e.y >= h - 32) r = -1; else { int i = (e.y - 8) / 30; if (i < n && i < 16) r = i; } } } zw_close(d); return r; }
static void pbuild(zpdoc *d, const zpset *s, void *c) {
    zpflow f; zp_flow_init(&f, d, 72); zp_flow_newpage(&f); f.y = zp_ph(d) / 3; zp_para(&f, ZPF_SERIFB, 30, 0, title[0] ? title : _("Sin titulo"), 1, 0); f.num = 1;
    for (int i = 0; i < ns; i++) { sec_t *x = &S[i]; if (!x->len) continue; zp_flow_newpage(&f); f.y += 40; zp_para(&f, ZPF_SERIFB, 20, 0, x->name, 0, 24); const char *p = x->txt; char *ln = malloc(x->len + 1);
        while (*p) { const char *e = strchr(p, '\n'); long l = e ? e - p : (long)strlen(p); memcpy(ln, p, l); ln[l] = 0; if (ln[0] == '#') { char *h = ln; while (*h == '#') h++; while (*h == ' ') h++; zp_para(&f, ZPF_SERIFB, 15, 0, h, 0, 8); } else zp_para(&f, ZPF_SERIF, 12, 0, ln, 0, 6); if (!e) break; p = e + 1; }
        free(ln); }
}
static void print_book(void) { keep(); zp_dialog(title[0] ? title : "Sin titulo", pbuild, 0); }
static void projects(void) { static char names[17][120]; const char *it[17]; int n = 1; strcpy(names[0], _("Libro nuevo")); it[0] = names[0]; zdirent d; for (int i = 0; n < 16 && !z_readdir(dir, i, &d); i++) if (z_ends(d.name, ".zes")) { strncpy0(names[n], d.name, 120); it[n] = names[n]; n++; } int r = pick("Proyectos", it, n); if (r < 0) return; if (dirty) save(); if (r == 0) newbook(); else { char p[340]; snprintf(p, 340, "%s/%s", dir, names[r]); int e = load(p); if (e) snprintf(st, 100, "Error: %s", z_errstr(e)); } }
int main(const char *a) { int wp; a = z_print_arg(a, &wp);
    zoom = TH.text_sc; char base[120]; z_docdir(base); snprintf(dir, 200, "%s/ESCRITOR", base); z_mkdir(dir); zsys s; z_sysinfo(&s); te_init(&T); W = zw_new("Escritor", 20, 40, MIN(1000, (int)s.scr_w - 40), MIN(680, (int)s.scr_h - 110), WF_DECOR | WF_RESIZE); newbook(); if (a[0]) { if (z_ends(a, ".zes")) load(a); else import_(a); } else { char p[340]; zdirent d; int best = 0; for (int i = 0; !z_readdir(dir, i, &d); i++) if (z_ends(d.name, ".zes")) { snprintf(p, 340, "%s/%s", dir, d.name); best = 1; } if (best) load(p); } start_words = total_words(); strcpy(st, _("Listo")); draw(); if (wp) { print_book(); draw(); } zevent e; int drag = 0; u64 lastsave = z_ms();
    for (;;) { int g = z_event(&e, 1000); if (g && e.type == EV_REDRAW) { redraw(); continue; } u64 now = z_ms(); if (dirty && now - last_edit > 3000 && now - lastsave > 5000) { save(); lastsave = now; redraw(); } if (!g) continue; int fw = FW && e.win == (u32)FW->id; if (e.win != (u32)W->id && !fw) continue; if (!fw) ui_edit_menu(W, &e); if (e.type == EV_KEY && e.ch == 16) { print_book(); redraw(); continue; }
        if (e.type == EV_CLOSE) { if (dirty) save(); return 0; } if (e.type == EV_RESIZE) { zw_resized(W, e.x, e.y); T.changed = 1; draw(); continue; }
        if (e.type == EV_KEY) { int k = e.key; if (k == 0x44) { toggle_focus(); continue; } if (FW && e.ch == 27) { toggle_focus(); continue; } if (k == 0x41) { dark = !dark; redraw(); continue; } if (k == 0x3F) { zoom = zoom == 1 ? 2 : 1; T.changed = 1; redraw(); continue; } if (k == 0x40) { typew = !typew; redraw(); continue; } if (e.ch == 19) { save(); redraw(); continue; }
            if ((e.mods & M_ALT) && (k == K_UP || k == K_DOWN) && cur >= 2 && cur < ns - 1) { int t = cur + (k == K_UP ? -1 : 1); if (t >= 2 && t < ns - 1) { keep(); sec_t x = S[cur]; S[cur] = S[t]; S[t] = x; cur = t; dirty = 1; last_edit = now; } redraw(); continue; }
            if (foc == 1) { if (e.ch == '\n' || e.ch == 27) foc = 0; else if (ui_input_key(title, 90, &tc, &e)) { dirty = 1; last_edit = now; } } else if (foc == 2) { if (e.ch == '\n' || e.ch == 27) foc = 0; else if (ui_input_key(S[cur].name, 70, &sc2, &e)) { dirty = 1; last_edit = now; } } else { int r = te_key(&T, &e, 20); if (r == 2) { dirty = 1; last_edit = now; st[0] = 0; } } redraw(); continue; }
        if (fw) { if (e.type == EV_DOWN) { int c = scols(FW->w), px = (FW->w - c * 8 * zoom) / 2; te_click(&T, e.x - px, e.y - 18, zoom, e.mods & M_SHIFT); draw_focus(); } continue; }
        if (e.type == EV_WHEEL) { if (e.x < SW) stop = MAX(0, MIN(stop - (int)e.key, ns - 1)); else { T.top = MAX(0, T.top - (int)e.key * 3); T.cur = T.ln ? T.ln[MIN(T.top + 2, T.nl - 1)] : 0; } draw(); continue; }
        if (e.type == EV_MOVE && drag) { int c = scols(W->w - SW), px = SW + (W->w - SW - c * 8 * zoom) / 2; te_click(&T, e.x - px, e.y - HH - 18, zoom, 1); draw(); continue; } if (e.type == EV_UP) { drag = 0; if (T.sel == T.cur) T.sel = -1; continue; } if (e.type != EV_DOWN) continue; int by = W->h - 146;
        if (e.x < SW) { if (e.y >= 70 && e.y < 96) { foc = 1; tc = strlen(title); } else if (e.y >= 104 && e.y < by - 4) { int i = stop + (e.y - 104) / 24; if (i < ns) go(i); } else if (e.y >= by && e.y < by + 26) { if (e.x < 118) { keep(); char n[40]; snprintf(n, 40, _("Capitulo %d"), chap_count() + 1); memmove(&S[ns], &S[ns - 1], sizeof S[0]); ns--; sec_add(n, "", 0); ns++; go(ns - 2); dirty = 1; last_edit = now; } else if (cur >= 2 && cur < ns - 1 && chap_count() > 1) { char q[120]; snprintf(q, 120, _("Borrar %.60s?"), S[cur].name); if (ui_confirm("Borrar capitulo", q)) { free(S[cur].txt); memmove(&S[cur], &S[cur + 1], (ns - cur - 1) * sizeof S[0]); ns--; if (cur >= ns - 1) cur = ns - 2; te_set(&T, S[cur].txt, S[cur].len); dirty = 1; last_edit = now; } } } else if (e.y >= by + 30 && e.y < by + 56) { if (e.x < 118) projects(); else { const char *E[] = {"1. Texto (.txt)", "2. Markdown (.md)", "3. Pagina web (.html)", "4. RTF (.rtf)", "5. Word (.docx)", "6. Imprimir o guardar como PDF"}; int r = pick("Exportar libro", E, 6); if (r == 5) print_book(); else if (r >= 0) export_(r); } } else if (e.y >= by + 60 && e.y < by + 86) toggle_focus(); if (FW) continue; }
        else if (e.y < HH) { if (e.x >= W->w - 62) save(); else if (e.x >= W->w - 110) dark = !dark; else if (e.x >= W->w - 150) { zoom = zoom == 1 ? 2 : 1; T.changed = 1; } else if (e.x < SW + 292 && cur >= 2 && cur < ns - 1) { foc = 2; sc2 = strlen(S[cur].name); } }
        else { foc = 0; int c = scols(W->w - SW), px = SW + (W->w - SW - c * 8 * zoom) / 2; te_click(&T, e.x - px, e.y - HH - 18, zoom, e.mods & M_SHIFT); if (!(e.mods & M_SHIFT)) T.sel = T.cur; drag = 1; } draw(); }
}
